import{_ as t,o as a,c as r,a3 as o}from"./chunks/framework.Ch_0qWu9.js";const u=JSON.parse('{"title":"Resource access and distribution conditions","description":"","frontmatter":{"sourcePath":"docs/licenses/distribution.md","sourceUrl":"https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/distribution.md","alternateUrl":"/TCSExam/docs/zh/licenses/distribution/","alternateAnchors":{"resource-access-and-distribution-conditions":"resource-access-and-distribution-conditions","apply-conditions-to-the-selected-material":"apply-conditions-to-the-selected-material","data-and-task-materials":"data-and-task-materials","tools-and-runtime-components":"tools-and-runtime-components"}},"headers":[],"relativePath":"licenses/distribution/index.md","filePath":"licenses/distribution/index.md"}'),n={name:"licenses/distribution/index.md"};function i(s,e,d,c,l,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="resource-access-and-distribution-conditions" tabindex="-1">Resource access and distribution conditions <a class="header-anchor" href="#resource-access-and-distribution-conditions" aria-label="Permalink to &quot;Resource access and distribution conditions&quot;">​</a></h1><p>This guide lists access routes and sharing conditions for TCSExam resources. It is for users preparing data locally or distributing source, data or images.</p><h2 id="apply-conditions-to-the-selected-material" tabindex="-1">Apply conditions to the selected material <a class="header-anchor" href="#apply-conditions-to-the-selected-material" aria-label="Permalink to &quot;Apply conditions to the selected material&quot;">​</a></h2><p>Use <a href="/TCSExam/docs/resources/"><code>tcsexam build</code></a> to acquire fixed official inputs, verify and transform them, and assemble local images. Resources marked <code>local_prepare</code> can be prepared locally under their source terms. <code>private_only</code> excludes a material from public source export and public image distribution.</p><p>Before redistributing a product, follow its resource-specific conditions below and retain the required source, attribution and notices. Each row applies to the named material and version; an image combines the conditions of all its inputs and inherited layers. Locally generated products retain applicable restrictions on their source materials. Use the linked records for exact product IDs and file scopes.</p><h2 id="data-and-task-materials" tabindex="-1">Data and task materials <a class="header-anchor" href="#data-and-task-materials" aria-label="Permalink to &quot;Data and task materials&quot;">​</a></h2><p>Read each row by resource. Source links and records identify the covered inputs; sharing conditions apply to the resulting material as well as its containing images.</p><table tabindex="0"><thead><tr><th>Resource</th><th>Access and source</th><th>Terms and handling</th></tr></thead><tbody><tr><td>Original code, checkers, scripts and build configuration</td><td>Repository source</td><td>Apache-2.0 where project contributors hold the applicable rights. Retain author notices, <code>LICENSE</code> and <code>NOTICE</code>, and identify modifications.</td></tr><tr><td>Original task statements, explanatory documentation and website content</td><td>Repository source and website repository</td><td>CC BY 4.0 where project contributors hold the applicable rights. Retain attribution and identify modifications.</td></tr><tr><td>QBF evaluation data: thirteen public instances and 57 hidden transformed instances</td><td><a href="https://doi.org/10.5281/zenodo.18832723" target="_blank" rel="noreferrer">ParaProofa v1 supplement</a>, by Mark Peyrer, Maximilian Heisinger and Martina Seidl; <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/qbf-data-distribution-source.json" target="_blank" rel="noreferrer">fixed source record</a></td><td>CC BY 4.0, with attribution to supplement authors and original instance families. The three BMC instances <code>ex018</code>, <code>ex019</code> and <code>ex020</code> additionally retain University of Toronto 2007 non-commercial teaching and research terms, including no-fee, notice and publicity conditions. The fixed-product scope is listed below. Software in the supplement retains its own licenses.</td></tr><tr><td>BPPLIB instances, packings and registry-table extraction</td><td>Fixed official files from <a href="https://github.com/mdelorme2/BPPLIB" target="_blank" rel="noreferrer">BPPLIB</a>; <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/bpplib-reconstruction.json" target="_blank" rel="noreferrer">preparation record</a></td><td>CC BY-NC-ND 4.0. Preserve attribution, non-commercial and no-derivatives conditions. Generated files and all containing images remain local-only products; keep them out of public registries and downloads.</td></tr><tr><td>PACE 2019 Vertex Cover public development data</td><td><a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/vc-pace2019-source.json" target="_blank" rel="noreferrer">Source record</a> for the public-v2 archive; <a href="https://zenodo.org/records/3368306" target="_blank" rel="noreferrer">Zenodo dataset</a></td><td>CC BY 4.0 by M. Ayaz Dzulfikar, Johannes K. Fichte and Markus Hecher. Scope: <code>solver-vc-pace2019-development-data</code>, containing 100 odd-numbered public instances recompressed with XZ 5.2.5. Retain the CC BY text, <code>PACE2019-VC-NOTICE.txt</code>, source and PACE report links, graph-family attribution and recompression notes.</td></tr><tr><td>PACE 2021 Cluster Editing public development data</td><td><a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/ce-pace2021-source.json" target="_blank" rel="noreferrer">Pinned source and XZ reconstruction</a></td><td>CC0-1.0 covers the 100 odd-numbered public instances in <code>solver-ce-pace2021-development-data</code>. Include the CC0 text and source record.</td></tr><tr><td>PACE 2022 Directed Feedback Vertex Set public development data</td><td><a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/dfvs-pace2022-source.json" target="_blank" rel="noreferrer">Pinned source and reconstruction</a></td><td>Local preparation only: the official archive has no data license. Retain its notices and keep the official archive, generated instances and containing images out of public distribution. The PACE report has its own CC BY 4.0 license.</td></tr><tr><td>PACE 2024 OSCM public development data</td><td><a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/oscm-pace2024-source.json" target="_blank" rel="noreferrer">Two pinned official archives</a></td><td>The combined 173-file product is local-only. MIT covers the 60 medium and thirteen tiny test-set instances; the 100 Exact Track instances have no data license. Retain the source notice and test-set MIT text. Keep both official archives and the combined generated product and containing images out of public distribution. Upstream <code>.sol</code> files are excluded from preparation.</td></tr><tr><td>AHC058 public development data</td><td><a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/ahc058-atcoder-source.json" target="_blank" rel="noreferrer">Official AtCoder archive and locked generator</a></td><td>Local preparation only: no open redistribution license is established for the statement, inputs, generator, scorer or visualizer. Retain the source notice. Keep the official archive, generated instances and containing images out of public distribution.</td></tr><tr><td>Course-timetabling instances</td><td><a href="https://github.com/iolab-uniud/cb-ctt" target="_blank" rel="noreferrer">cb-ctt</a> for twenty corresponding instances and transformations; <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/ctt-source-comparison.json" target="_blank" rel="noreferrer">source comparison</a></td><td>CC BY 4.0 from the original authors. Identify format/name changes, including <code>comp15</code> corresponding to official <code>comp03</code>. <code>comp11</code> and OptHub solutions require their own source terms; obtain them from the <a href="https://www.eeecs.qub.ac.uk/itc2007/" target="_blank" rel="noreferrer">official sources</a>. Their redistribution terms are unconfirmed.</td></tr><tr><td>IWLS 2022 public truth tables</td><td><a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/logic-syn-iwls2023-source.json" target="_blank" rel="noreferrer">Pinned source and transformations</a></td><td>Retain IWLS 2022&#39;s MIT license for the 100 public truth tables and identify transformations. The ABC archive has separate software terms below.</td></tr><tr><td>MQLib instances</td><td><a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/mqlib-family-license-review.json" target="_blank" rel="noreferrer">Family-specific sources and license record</a></td><td>OR-Library instances <code>g001642</code>, <code>g002564</code> and <code>g002776</code> have a documented MIT basis; retain J. E. Beasley&#39;s attribution and full license. Acquire other families from their sources under their individual terms.</td></tr><tr><td>ROADEF/EURO 2012 instances and reference assignments</td><td><a href="https://github.com/google/or-tools/tree/06376d5ff5bbaead64e9b2df61ccbe74e99e5f8c/data/roadef_challenge_2011/solution_checker" target="_blank" rel="noreferrer">Pinned Google OR-Tools source</a>; <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/roadef-hidden-source-chain.json" target="_blank" rel="noreferrer">source-chain record</a></td><td>Included instances and checker source are Apache-2.0. Retain Google attribution, license and modification notes. Reference assignments are project-generated numerical outputs recorded separately. Obtain the challenge PDF from the <a href="https://www.roadef.org/challenge/2012/en/sujet.php" target="_blank" rel="noreferrer">official page</a>; its redistribution terms are unconfirmed.</td></tr><tr><td>MaxSAT hidden data</td><td><a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/assets/data/solver/solver-maxsat-mse-judging-data-recipe.json" target="_blank" rel="noreferrer">Pinned official Zenodo archive and reconstruction recipe</a></td><td>The MaxSAT Evaluation 2026 supplement is CC BY 4.0. Retain supplement and instance-family attribution from the <a href="/TCSExam/docs/licenses/THIRD_PARTY_NOTICES/#additional-full-materials">third-party notices</a>. Included solver programs retain their own licenses.</td></tr><tr><td>Reference-answer payloads</td><td><a href="/TCSExam/docs/oracle-answers/">Reference-answer handling</a></td><td>Keep concrete acceptance answers outside model-solving environments. They are private by default and unnecessary for ordinary builds and runs. Apply the explicit release interface and resource-specific conditions to an answer product authorized for distribution.</td></tr><tr><td>Papers, rules PDFs, model outputs and other external materials</td><td>Original sources and any material-specific license</td><td>Follow the terms for the material being shared. A software or dataset license applies only to its covered content.</td></tr></tbody></table><p>The fixed QBF product scope is <code>qbf-public</code>, <code>qbf-judging</code>, <code>qbf-qbfeval-online-development</code>, <code>qbf-qbfeval-offline-development</code>, <code>qbf-qbfeval-online-backend</code>, <code>qbf-qbfeval-offline-verifier</code> and <code>backend-public-online-qbf-qbfeval</code>. The associated fixed transformed data, standard answers and <code>ex*</code> mapping have the data permission recorded in the <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/qbf-data-distribution-source.json" target="_blank" rel="noreferrer">source record</a>. Keep applicable software, system and per-instance notices with any distributed product, and follow the answer-handling guide for answer payloads.</p><h2 id="tools-and-runtime-components" tabindex="-1">Tools and runtime components <a class="header-anchor" href="#tools-and-runtime-components" aria-label="Permalink to &quot;Tools and runtime components&quot;">​</a></h2><p>Read each row for the component&#39;s license and any source or replacement requirements.</p><table tabindex="0"><thead><tr><th>Resource</th><th>Access and source</th><th>Terms and handling</th></tr></thead><tbody><tr><td>PACE 2021 Cluster Editing and PACE 2022 Directed Feedback Vertex Set verifiers</td><td>Pinned official <a href="https://pacechallenge.org/2021/verifier.zip" target="_blank" rel="noreferrer">2021 ZIP</a> and <a href="https://pacechallenge.org/2022/verifier.tar.gz" target="_blank" rel="noreferrer">2022 tar.gz</a>, compiled by the local recipes</td><td>Redistribution terms are unconfirmed. Download and compile locally, retain upstream notices and keep the source snapshots and resulting images private.</td></tr><tr><td>VC public self-test judge</td><td><a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/vc-public-judge-image.json" target="_blank" rel="noreferrer">Component requirements</a> for <code>backend-public-online-vc-pace2019</code></td><td>Retain project and data licenses, vc_validate corresponding source and build instructions, and applicable system-package source materials.</td></tr><tr><td>OSCM NumPy development tool</td><td><a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/oscm-pace2024-development-tools-source.json" target="_blank" rel="noreferrer">Pinned NumPy 2.2.6 wheel</a></td><td>Local preparation only. The recipe verifies the wheel and its RECORD entries and retains four upstream notices. Bundled-dependency source obligations remain unconfirmed; keep the wheel, tools image and containing images private.</td></tr><tr><td>CPSolver, dom4j and log4j</td><td><a href="/TCSExam/docs/licenses/cpsolver-source/">Source, build and replacement guide</a></td><td>Java sources: LGPL-3.0-or-later; original Ant files: LGPL-2.1-or-later; dom4j: five-clause BSD-style terms; log4j: Apache Software License 1.1. Include required corresponding source, build materials and complete notices with distributed binaries.</td></tr><tr><td>Qute, drat-trim and qrp2rup</td><td>Pinned sources in the <a href="/TCSExam/docs/licenses/THIRD_PARTY_NOTICES/">third-party notices</a></td><td>Qute&#39;s later MIT notice has unconfirmed applicability to its older snapshot; retain the original revision and version comparison. drat-trim is MIT. qrp2rup is CC BY 4.0 under the author&#39;s supplement: attribute it, mark changes and provide its source with binaries. Preserve MiniSat and docopt.cpp MIT/Boost notices separately.</td></tr><tr><td>MQLib software</td><td><a href="https://github.com/MQLib/MQLib" target="_blank" rel="noreferrer">MQLib repository</a></td><td>MIT. Retain copyright and license, with notices of modifications. Instance data has the family-specific terms above.</td></tr><tr><td>ABC source</td><td><a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/logic-syn-iwls2023-source.json" target="_blank" rel="noreferrer">Pinned source record</a></td><td>Retain the UC Regents BSD-style notice.</td></tr><tr><td>Lean, mathlib, elan and system packages</td><td><a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/system-license-materials.json" target="_blank" rel="noreferrer">System sources</a>, <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/lean-public-rebuild-system-materials.json" target="_blank" rel="noreferrer">additional package descriptors</a> and <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/lean-public-rebuild-mathlib-materials.json" target="_blank" rel="noreferrer">mathlib inventory</a></td><td>Retain each component&#39;s notices and provide complete corresponding source where its license requires it. Match source, compiled cache and version.</td></tr><tr><td>Agent tools</td><td>Pinned Harbor runtime installer; <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/claude-code-distribution.json" target="_blank" rel="noreferrer">agent-tool record</a></td><td>Agent packages retain their own licenses. The recorded Claude Code package has an All rights reserved notice and no general redistribution grant; install it at runtime and exclude it from distributed environment images.</td></tr><tr><td>Graphviz in ProofWidgets and other browser components</td><td><a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/proofwidgets-embedded-components.json" target="_blank" rel="noreferrer">Embedded component record</a> and <a href="/TCSExam/docs/environments/lean-base/graphviz-epl/SOURCE-OFFER/">Graphviz source materials</a></td><td>Graphviz is EPL-2.0 and the wrapper is Apache-2.0. Prepare fixed source archives with <code>tcsexam source-inputs</code>. Retain EPL text, corresponding Graphviz source, wrapper changes and build rules, and applicable Lake/browser/npm notices installed under <code>/usr/share/doc/tcsexam/</code>.</td></tr></tbody></table><p>Use the <a href="/TCSExam/docs/licenses/THIRD_PARTY_NOTICES/">third-party notices</a> for attribution text and <a href="/TCSExam/docs/licenses/full-review/">component records</a> for pinned file inventories. The <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/assets/files.json" target="_blank" rel="noreferrer">file manifest</a> and <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/assets/images.json" target="_blank" rel="noreferrer">image manifest</a> record input paths, product identities and available acquisition addresses.</p>',13)])])}const f=t(n,[["render",i]]);export{u as __pageData,f as default};
